#pragma once#include <vector>#include "ShemeData.h"#include "baseint.h"#include "Names.h"#include "UniBuffer.h"#include <RsuX.h>#include <ServerExPluginTypes.h>struct SExtensions{  tExtractumRSU pExtractumRSUCall;  tSizeShRSU  pSizeShRSUCall;  tPutModelRSU pPutModelRSUCall;  tGetRsuData pGetRsuData;  tAlarmsSupport pAlarmsSupport;  tAnyGetSetRequest pAnyOtherRequest;  tAlarmsSupport pMessagesSupport;  tAlarmsSupport pEventsSupport;  tFindConnPointEx pFindConnPointEx;};enum{  ecCount = 10};extern SExtensions g_extensionsCont[ecCount];struct DataEntry{  CBase*     pBase;  EDataTypes mType;  char       name[128];  KRsuX pnt;  DataEntry( CBase* pB, char* pszName, EDataTypes mT, KRsuX &_pnt )  : pBase( pB )  , mType( mT )  , pnt( _pnt )  {    strcpy_s( name, pszName );  };};typedef std::vector<DataEntry> DataType;class CMemBuffer : public CMemFile{public:  BYTE* GetBuffer()   {     if (m_nFileSize)       return m_lpBuffer;     return NULL;  }};//class for local-thread storageclass CServerThread  {  public:    CServerThread(HANDLE);    virtual ~CServerThread(void);    DWORD dwRequestSize;    HANDLE m_hPipe;    DataType arrData;    char m_szCompName[64];    //    void Run (); //main loop    void ChangeBusy(CBase* pB, int n);    CBase* FindBase( DWORD TypeID, char* szName, CShBase* pSB, KRsuX &pnt );    //    void Extractum( DWORD type, CShBase* pSB, CBase *pB); //pB ->  pSB    void Extractum( DWORD type, CShBase* pSB, KRsuX &pnt );    void GetAnswerToRequest(CMemBuffer& Reply);    void GetFromReq( DWORD& type, char*& name, size_t& pos);    void GetFromReq( char* &name, size_t &pos );    BYTE* GetRequest();    BOOL PutReply (LPCVOID pReply, DWORD dwSize);    BOOL PutModelLocal( LPCTSTR szUser, SSendToModel& send );    //    int  SizeSh(DWORD type, KRsuX *pPnt = NULL );    //  private:// Передача данных Модель -> АРМ Оператора    void MnemoGet     (CMemBuffer& Reply);    void MnemoRefresh (CMemBuffer& Reply);    void GetAlarms    (CMemBuffer& Reply, DWORD rsuID );    void GetEvents    (CMemBuffer& Reply, DWORD rsuID);    void GetMsgToO    (CMemBuffer& Reply, DWORD rsuID);    void GetFileData  (CMemBuffer& Reply);  private:    CBase* FindConnPointLocal( LPCSTR ObjName, DWORD TypeID );  private: // Управление моделью    void ModelStart   (size_t& pos);    void ModelStop    (size_t& pos);    void ModelPause   (size_t& pos);    void ModelContinue(size_t& pos);    void ModelDefect  (size_t& pos);  private:    struct SUniSh : public SUniChar      {      SUniSh() : SUniChar(1024)        {        };      CShBase* Sh()        {        return (CShBase*)m_szBuffer;        };      bool Resize( int nSize )        {        if ( nSize <= 0 ) return false;        nSize += sizeof(CShBase)*2;        if ( nSize <= m_nMaxBuff ) return true;        return Realloc( nSize - Count() );        }      };    SUniSh mSh;    int   m_sizeReq;    BYTE *m_pRequest;    BYTE ModelStatus;  };//